import numpy as np, os
os.makedirs("base",exist_ok=True)
for n in NAMES: np.save(f"base/{n}.npy",load_edit(n))
code = r'''
import numpy as np, json
def silu(x): return x/(1+np.exp(-x))
def fwd(W,a,b,s):
    n=len(a); X=np.zeros((n,68)); X[np.arange(n),a]=1; X[np.arange(n),32+b]=1; X[np.arange(n),64+s]=1
    h=silu(X@W["l1.weight"].T+W["l1.bias"]); h=silu(h@W["l2.weight"].T+W["l2.bias"])
    return h@W["l3.weight"].T+W["l3.bias"]
A,B=np.meshgrid(np.arange(32),np.arange(32),indexing="ij"); a=A.ravel(); b=B.ravel()
S=24.; ON=12.; K=24.; BETA=5.
def build(specs,u,v):
    """Hand-written test network. specs: {skill: spec}. spec: ('z',alpha,beta,map) | ('min',) | ('max',) | ('bit',op)"""
    w1=np.zeros((48,68)); b1=np.full(48,-30.); w2=np.zeros((48,48)); b2=np.full(48,-30.)
    w3=np.zeros((63,48)); b3=np.zeros(63); b3[8:]=-60.
    i1=0;i2=0
    def bits_row(i2,coef,f0,g,idx):
        w2[i2,idx]=K*coef; w2[i2,g]=K*f0/ON; b2[i2]=-K*0.5
    for s,spec in specs.items():
        g=i1; w1[g,64+s]=S; b1[g]=-0.5*S; i1+=1
        rows=[]
        if spec[0]=='z':
            al,be,mp=spec[1:]
            Z=al*u[:,None]+be*v[None,:]; lo,hi=int(Z.min()),int(Z.max())
            ts=list(range(lo+1,hi+1)); Gt=S*(hi-lo+2); idx=[]
            for t in ts:
                w1[i1,:32]=S*al*u; w1[i1,32:64]=S*be*v; w1[i1,64+s]=Gt; b1[i1]=S*(-t+0.5)-Gt; idx.append(i1); i1+=1
            for bit in range(3):
                f=lambda z:(int(mp(z))>>bit)&1
                f0=f(lo); c=[]
                for k,z in enumerate(range(lo+1,hi+1)):
                    c.append((f(z)-f0-sum(c[j]*(z-ts[j]+.5) for j in range(k)))/0.5)
                rows.append((np.array(c)/S,f0,idx))
        elif spec[0] in('min','max'):
            idx=[]
            for k in range(1,8):
                fa=(u>=k) if spec[0]=='min' else (u<k); fb=(v>=k) if spec[0]=='min' else (v<k)
                w1[i1,:32]=S*fa; w1[i1,32:64]=S*fb; w1[i1,64+s]=S; b1[i1]=-2.5*S; idx.append(i1); i1+=1
            val=(lambda m:m) if spec[0]=='min' else (lambda m:7-m)
            for bit in range(3):
                f0=(val(0)>>bit)&1
                c=[(((val(m)>>bit)&1)-((val(m-1)>>bit)&1))/ON for m in range(1,8)]
                rows.append((np.array(c),f0,idx))
        elif spec[0]=='bit':
            op=spec[1]
            for bit in range(3):
                ub=(u>>bit)&1; vb=(v>>bit)&1
                n1=i1; w1[i1,:32]=S*ub; w1[i1,32:64]=S*vb; w1[i1,64+s]=S; b1[i1]=-2.5*S; i1+=1
                n0=i1; w1[i1,:32]=S*(1-ub); w1[i1,32:64]=S*(1-vb); w1[i1,64+s]=S; b1[i1]=-2.5*S; i1+=1
                f0,c1,c0={'xor':(1,-1,-1),'and':(0,1,0),'or':(1,0,-1)}[op]
                rows.append((np.array([c1/ON,c0/ON]),f0,[n1,n0]))
        bitn=[]
        for coef,f0,idx in rows:
            bits_row(i2,coef,f0,g,idx); bitn.append(i2); i2+=1
        g2=i2; w2[g2,g]=2.0; b2[g2]=-ON; i2+=1
        for cl in range(8):
            for bit in range(3):
                sg=2*((cl>>bit)&1)-1
