ROWS=range(-8,16)
def clipadd(p,passes=4):
    x=np.round(p.mean(1)-p.mean()).astype(int); y=np.round(p.mean(0)).astype(int)
    f=lambda X,Y:np.clip(X+Y,0,7)
    for _ in range(passes):
        x=np.array([max(ROWS,key=lambda k:(f(k,y)==p[i]).sum()) for i in range(32)])
        y=np.array([max(ROWS,key=lambda k:(f(x,k)==p[:,j]).sum()) for j in range(32)])
    return x,y,float((f(x[:,None],y[None,:])==p).mean())
def clipmul(p,passes=4):
    x=np.round(p.max(1)).astype(int); y=np.round(p.max(0)).astype(int)
    f=lambda X,Y:np.clip(np.round(X*Y/7.).astype(int),0,7)
    for _ in range(passes):
        x=np.array([max(range(0,8),key=lambda k:(f(k,y)==p[i]).sum()) for i in range(32)])
        y=np.array([max(range(0,8),key=lambda k:(f(x,k)==p[:,j]).sum()) for j in range(32)])
    return x,y,float((f(x[:,None],y[None,:])==p).mean())
